Proof: We will show that each binary number $$$A, B, C$$$ can be assigned its own remainder modulo $$$3$$$. Let us associate $$$1$$$ with $$$A$$$, $$$B$$$ — $$$(2^k + 1)  mod 3$$$, and $$$C$$$ — $$$(2^{k-1}+ 1)  mod 3$$$ (it is easy to verify that all three remainders are distinct). Then suppose we are at the $$$t$$$th step of the process, and before it it is true that each filled row contains a corresponding binary number from $$$A, B, C$$$. It suffices to show that after this step the correspondence remains true. To do this, it is enough to understand that $$$ rac{p_{j}+p_{j+1}}{2} 
eq p_j$$$ and $$$ rac{p_{j}+p_{j+1}}{2} 
eq p_{j+1}$$$ modulo $$$3$$$ (this is equivalent to $$$p_j 
eq p_{j+1}$$$, which can also be fixed as an invariant), since then this remainder is equal to the one that is not among $$$a_{p_j}$$$ and $$$a_{p_{j+1}}$$$, and therefore corresponds to the remaining number that is obtained by applying the XOR operation to the numbers $$$a_{p_j}$$$ and $$$a_{p_{j+1}}$$$.

#include <bits/stdc++.h>

using namespace std;

void solve() {
    int n, k;
    cin >> n >> k;
    vector<int> a(n), b(n);
    char g;
    for (int i = 0; i < n; ++i) {
        cin >> g;
        a[i] = g - '0';
    }
    for (int i = 0; i < n; ++i) {
        cin >> g;
        b[i] = g - '0';
    }
    vector<int> c(4);
    for (int i = 0; i < n; ++i) {
        int x = 2 * a[i] + b[i];
        c[x]++;
    }

    if (k % 2) {
        long long p = 0, q = 0, r = 0;
        p = c[0] + c[1];
        q = c[0] + c[3];
        r = c[0] + c[2];
        cout << (((1ll << k) + 1) / 3) * (p * (n-p) + q * (n - q) + r * (n - r)) << "\n";
    } else {
        long long p = 0, q = 0, r = 0;
        p = c[0] + c[1];
        q = c[0] + c[2];
        r = c[0] + c[3];
        cout << (((1ll << k) + 1) / 3) * (p * (n-p) + q * (n - q) + r * (n - r)) + p * (n - p) + q * (n - q) << "\n";
    }
}

