map<array<int, 4>, int> mp;

int solve(int l, int a, int b, int c) {
    array<int, 4> t = {l, a, b, c};
    if (mp.find(t) == mp.end()) {
        if (l == 0) mp[t] = a + b;
        else mp[t] = solve(l - 1, c, a, b) + solve(l - 1, b, c, a) - c;
