using pii = pair<int, int>;

void solve() {
    int n;
    cin >> n;
    vector<int> h(n);
    for (int i = 0; i < n; i++) cin >> h[i];
    int t = max_element(h.begin(), h.end()) - h.begin();

    vector<int> ls(n), rs(n);

    stack<pii> sm;
    sm.push({1e18, 0});
    for (int ti = 1; ti < n; ti++) {
        int i = (ti + t) % n;
        int s = ls[i] + h[i], c = 1;
        while (sm.top().first <= h[i]) {
            s += sm.top().second * (h[i] - sm.top().first);
            c += sm.top().second;
            sm.pop();
        }
        sm.push({h[i], c});
        ls[(i + 1) % n] = s;
    }

    sm = stack<pii>();
    sm.push({1e18, 0});
    for (int ti = 1; ti < n; ti++) {
        int i = (t + n - ti) % n;
        int s = rs[(i + 1) % n] + h[i], c = 1;
        while (sm.top().first <= h[i]) {
            s += sm.top().second * (h[i] - sm.top().first);
            c += sm.top().second;
            sm.pop();
        }
        sm.push({h[i], c});
        rs[i] = s;
    }

    for (int i = 0; i < n; i++) {
        cout << ls[i] + rs[i] << " ";
    }
    cout << "\n";
}

